    "type": "p",
    "text": "Pentru a transformă intenția în capacitate reală, masterplanul propune un pachet integrat de măsuri: modernizarea fasciculelor de cale ferată din incintă portuară, extinderea terminalelor intermodale, îmbunătățirea legăturilor cu liniile magistrale 800 și 900 și dezvoltarea de servicii feroviare regulate (trenuri-bloc). Pe latură fluvială, terminalul fluvial al Constanței trebuie să funcționeze ca platformă de transbordare între nave maritime și barje destinate porturilor interioare. Indicatorul cheie de monitorizat este cotă modală a mărfii pe ieșirea din port, iar succesul se măsoară prin scăderea numărului de camioane pe tonă transportată. Această abordare aliniază obiectivele de competitivitate cu cele de mediu."
