    "text": "Sistemul portuar contribuie semnificativ la produsul intern brut regional și național, prin valoarea adăugată generată de operațiunile portuare, de lanțul logistic și de industriile asociate. Cuantificarea acestei contribuții, prin studii de impact economic, fundamentează importanță strategică a investițiilor portuare și argumentul pentru prioritizarea lor în politică de dezvoltare. Contribuția la PIB include valoarea adăugată directă a sectorului portuar, efectele indirecte asupra lanțului de furnizori și efectele induse asupra economiei. Pentru regiunea Dobrogei, sistemul portuar reprezintă un motor economic central, iar pentru economia națională, o poartă comercială esențială."
