    "type": "p",
    "text": "Capacitatea instituțională și de planificare este o condiție transversală pentru succesul implementării masterplanului. Indicatorii relevanți sunt capacitatea de pregătire și implementare a proiectelor, rată de absorbție a finanțării și respectarea termenelor și bugetelor. Master Planul subliniază ca constrângerea reală a dezvoltării este adesea capacitatea de implementare, nu finanțarea. Investiția în capacitatea instituțională, prin personal calificat, proceduri eficiente și asistență tehnică, este o prioritate transversală. O capacitate instituțională solidă transformă strategia și finanțarea în investiții realizate, depășind constrângerea istorică care a limitat dezvoltarea infrastructurii de transport în regiune."
