    "text": "Îmbunătățirea conexiunii maritim-fluvial presupune dezvoltarea capacității terminalului fluvial, eficientizarea transbordării și dezvoltarea de servicii fluviale regulate care fac navetă între Constanța și porturile dunărene. În prezent, cotă transportului fluvial în evacuarea mărfii din port este redusă, semnalând o sub-utilizare a acestei conexiuni strategice. Master Planul recomandă dezvoltarea terminalului fluvial și a serviciilor de barje regulate, pentru a activă fluxul maritim-fluvial. Creșterea utilizării conexiunii fluviale ar reduce presiunea pe transportul terestru și ar valorifica avantajul structural al Constanței ca port fluvio-maritim."
